-- E-Learn 3cayxanh v5 | MySQL 8.0.16+
-- Recommended install: composer install && php artisan migrate --seed
-- This file is a compact reference of the principal schema; migrations also add sessions, password resets, views, checks and triggers.
CREATE DATABASE IF NOT EXISTS elearn_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE elearn_db;
CREATE TABLE users (user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, user_code VARCHAR(40) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('student','teacher','admin') NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Hoạt động', remember_token VARCHAR(100) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, INDEX ix_users_role_status(role,status)) ENGINE=InnoDB;
CREATE TABLE courses (course_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_code VARCHAR(40) NOT NULL UNIQUE, course_name VARCHAR(200) NOT NULL, teacher_id BIGINT UNSIGNED NOT NULL, term VARCHAR(100) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT NOT NULL, color VARCHAR(30) NOT NULL DEFAULT 'cover1', symbol VARCHAR(30) NOT NULL DEFAULT 'DB', created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_courses_teacher FOREIGN KEY(teacher_id) REFERENCES users(user_id) ON UPDATE CASCADE ON DELETE RESTRICT, INDEX ix_courses_teacher(teacher_id)) ENGINE=InnoDB;
CREATE TABLE enrollments (enrollment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, progress TINYINT UNSIGNED NOT NULL DEFAULT 0, enrolled_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT chk_enrollments_progress CHECK(progress BETWEEN 0 AND 100), CONSTRAINT fk_enrollments_course FOREIGN KEY(course_id) REFERENCES courses(course_id) ON UPDATE CASCADE ON DELETE CASCADE, CONSTRAINT fk_enrollments_student FOREIGN KEY(student_id) REFERENCES users(user_id) ON UPDATE CASCADE ON DELETE CASCADE, UNIQUE KEY uq_enrollments_course_student(course_id,student_id), INDEX ix_enrollments_student(student_id)) ENGINE=InnoDB;
CREATE TABLE lessons (lesson_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, title VARCHAR(220) NOT NULL, duration VARCHAR(40) NOT NULL DEFAULT '', lesson_type VARCHAR(80) NOT NULL DEFAULT 'Tài liệu', lesson_order INT UNSIGNED NOT NULL DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_lessons_course FOREIGN KEY(course_id) REFERENCES courses(course_id) ON UPDATE CASCADE ON DELETE CASCADE, INDEX ix_lessons_course_order(course_id,lesson_order)) ENGINE=InnoDB;
CREATE TABLE assignments (assignment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, title VARCHAR(220) NOT NULL, assignment_type VARCHAR(80) NOT NULL, due_date DATE NOT NULL, max_points DECIMAL(6,2) NOT NULL, is_open BOOLEAN NOT NULL DEFAULT TRUE, description TEXT NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT chk_assignments_max_points CHECK(max_points>0 AND max_points<=1000), CONSTRAINT fk_assignments_course FOREIGN KEY(course_id) REFERENCES courses(course_id) ON UPDATE CASCADE ON DELETE CASCADE, INDEX ix_assignments_course_due(course_id,due_date)) ENGINE=InnoDB;
CREATE TABLE submissions (submission_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assignment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, submitted_at TIMESTAMP NOT NULL, answer MEDIUMTEXT NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT fk_submissions_assignment FOREIGN KEY(assignment_id) REFERENCES assignments(assignment_id) ON UPDATE CASCADE ON DELETE CASCADE, CONSTRAINT fk_submissions_student FOREIGN KEY(student_id) REFERENCES users(user_id) ON UPDATE CASCADE ON DELETE CASCADE, UNIQUE KEY uq_submissions_assignment_student(assignment_id,student_id), INDEX ix_submissions_student_time(student_id,submitted_at)) ENGINE=InnoDB;
CREATE TABLE grades (grade_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, course_id BIGINT UNSIGNED NOT NULL, assignment_id BIGINT UNSIGNED NULL, submission_id BIGINT UNSIGNED NULL UNIQUE, work_title VARCHAR(220) NOT NULL, score DECIMAL(6,2) NOT NULL, max_score DECIMAL(6,2) NOT NULL, feedback TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, CONSTRAINT chk_grades_score CHECK(score>=0 AND max_score>0 AND score<=max_score), CONSTRAINT fk_grades_student FOREIGN KEY(student_id) REFERENCES users(user_id) ON UPDATE CASCADE ON DELETE CASCADE, CONSTRAINT fk_grades_course FOREIGN KEY(course_id) REFERENCES courses(course_id) ON UPDATE CASCADE ON DELETE CASCADE, CONSTRAINT fk_grades_assignment FOREIGN KEY(assignment_id) REFERENCES assignments(assignment_id) ON UPDATE CASCADE ON DELETE CASCADE, CONSTRAINT fk_grades_submission FOREIGN KEY(submission_id) REFERENCES submissions(submission_id) ON UPDATE CASCADE ON DELETE CASCADE, INDEX ix_grades_student_course(student_id,course_id)) ENGINE=InnoDB;
